  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease, border-color 0.2s ease;
}

.btn svg {
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn:active {
  transform: translateY(0) scale(0.985);
}

.btn.primary {
  color: var(--char-ink, #220812);
  background: linear-gradient(135deg, var(--accent-2), var(--accent) 58%, var(--accent));
  border-color: rgba(255, 255, 255, 0.24);
  box-shadow: 0 12px 28px color-mix(in srgb, var(--accent) 28%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.42);
}

.btn.primary:hover {
  box-shadow: 0 16px 34px color-mix(in srgb, var(--accent) 38%, transparent), inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

.btn.ghost {
  border-color: var(--line);
  background: rgba(255, 255, 255, 0.035);
  color: var(--text);
}

.btn.ghost:hover {
  border-color: var(--line-strong);
  background: rgba(255, 255, 255, 0.075);
}

.btn.large {
  min-height: 56px;
  padding: 0 27px;
  font-size: 12px;
}

.btn.xl {
  min-height: 60px;
  padding: 0 28px;
  font-size: 13px;
}

.btn kbd {
  display: inline-grid;
  place-items: center;
  width: 21px;
  height: 21px;
  margin-left: 2px;
  border: 1px solid rgba(0, 0, 0, 0.18);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.25);
  color: inherit;
  font-family: var(--font-body);
  font-size: 9px;
  font-weight: 900;
}

.content-note {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  max-width: 570px;
  color: var(--muted-2);
  font-size: 10px;
  line-height: 1.55;
}

.content-note span {
  color: var(--accent);
  font-size: 13px;
  line-height: 1.1;
}

/* --------------------------------------------------------------------------
   Portrait
   -------------------------------------------------------------------------- */

.portrait-svg {
  width: 100%;
  height: 100%;
}

.portrait-svg .portrait-aura {
  animation: aura-pulse 6s ease-in-out infinite;
  transform-origin: center;
}

@keyframes aura-pulse {
  0%, 100% { opacity: 0.3; transform: scale(0.98); }
  50% { opacity: 0.55; transform: scale(1.03); }
}

/* --------------------------------------------------------------------------
   How to play modal
   -------------------------------------------------------------------------- */

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 900;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(4, 2, 7, 0.76);
  backdrop-filter: blur(12px);
  animation: fade-in 0.2s ease both;
}

.modal-backdrop.is-closing {
  animation: fade-out 0.18s ease both;
}

.modal {
  position: relative;
  width: min(680px, 100%);
  max-height: min(88svh, 860px);
  overflow: auto;
  padding: clamp(26px, 4vw, 44px);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 28px;
  background:
    radial-gradient(circle at 90% 0, rgba(255, 79, 154, 0.18), transparent 38%),
    #170d1e;
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.7);
  animation: modal-in 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes fade-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes modal-in {
  from { opacity: 0; transform: translateY(18px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.modal-close {
  position: absolute;
  top: 18px;
  right: 18px;
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.04);
  color: var(--muted);
  cursor: pointer;
  transition: 0.2s ease;
}

.modal-close:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.1);
  transform: rotate(6deg);
}

.modal-close svg {
  width: 18px;
  height: 18px;
}

.how-modal h2 {
  margin: 9px 0 24px;
  font-size: clamp(38px, 6vw, 62px);
  line-height: 0.95;
  letter-spacing: -0.035em;
}

.how-modal h2 em {
  color: var(--pink);
  font-style: normal;
}

.how-steps {
  display: grid;
  gap: 8px;
}

.how-step {
  display: grid;
  grid-template-columns: 38px 1fr;
  gap: 14px;
  padding: 13px 0;
  border-top: 1px solid var(--line);
}

.how-step > span {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid color-mix(in srgb, var(--pink) 35%, transparent);
  border-radius: 9px;
  color: var(--pink);
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.05em;
}

.how-step b {
  display: block;
  margin-bottom: 2px;
  font-family: var(--font-display);
  font-size: 17px;
  font-weight: 600;
}

.how-step p {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.how-note {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  margin: 20px 0;
  padding: 14px 16px;
  border: 1px solid rgba(255, 79, 154, 0.22);
  border-radius: 15px;
  background: rgba(255, 79, 154, 0.055);
}

.how-note-heart {
  color: var(--pink);
}

.how-note p {
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.55;
}

.how-modal > .btn {
  width: 100%;
}

/* --------------------------------------------------------------------------
   Shared footer
   -------------------------------------------------------------------------- */

.title-footer,
.belly-footer,
.death-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;
  width: 100%;
  padding: 15px clamp(18px, 3.2vw, 52px) max(16px, env(safe-area-inset-bottom));
  color: var(--muted-2);
  font-family: var(--font-display);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.09em;
  line-height: 1.4;
  text-transform: uppercase;
}

.title-footer-right,
.belly-footer-right {
  color: var(--accent);
  text-align: right;
}

/* --------------------------------------------------------------------------
   Utility animations
   -------------------------------------------------------------------------- */

@keyframes float-y {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-12px); }
}

@keyframes pulse-heart {
  0%, 100% { transform: scale(1); }
  12% { transform: scale(1.16); }
  24% { transform: scale(0.97); }
  36% { transform: scale(1.08); }
  48% { transform: scale(1); }
}

@keyframes spin-slow {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ==========================================================================
   HEARTBITE — title + roster
   ========================================================================== */

/* --------------------------------------------------------------------------
   Title
   -------------------------------------------------------------------------- */

.title-screen {
  overflow: hidden;
  background:
    radial-gradient(circle at 72% 36%, color-mix(in srgb, var(--accent) 15%, transparent), transparent 34%),
    radial-gradient(circle at 11% 82%, rgba(121, 66, 255, 0.12), transparent 34%),
    linear-gradient(155deg, #100813 0%, #08040c 58%, #170815 100%);
}

.title-screen::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.028) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.028) 1px, transparent 1px);
  background-size: 74px 74px;
  mask-image: radial-gradient(circle at 50% 50%, #000 15%, transparent 76%);
  pointer-events: none;
}

.title-screen::after {
  content: '';
  position: absolute;
  top: 8%;
  right: -9%;
  z-index: 0;
  width: 54vw;
  height: 54vw;
  border: 1px solid rgba(255, 255, 255, 0.055);
  border-radius: 50%;
  box-shadow: 0 0 0 7vw rgba(255, 255, 255, 0.012), 0 0 0 14vw rgba(255, 255, 255, 0.01);
  pointer-events: none;
}

.title-orbs {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}

.title-orbs i {
  position: absolute;
  display: block;
  border-radius: 50%;
  filter: blur(75px);
  opacity: 0.18;
}

.title-orbs i:nth-child(1) {
  top: 17%;
  right: 14%;
  width: 320px;
  height: 320px;
  background: var(--accent);
}

.title-orbs i:nth-child(2) {
  left: -5%;
  bottom: 8%;
  width: 380px;
  height: 380px;
  background: #7b41ff;
}

.title-orbs i:nth-child(3) {
  top: 0;
  left: 37%;
  width: 200px;
  height: 200px;
  background: #ffd67a;
  opacity: 0.07;
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(470px, 1.05fr);
  align-items: center;
  gap: clamp(26px, 4vw, 76px);
  width: min(1500px, 100%);
  margin: auto;
  padding: 12px clamp(20px, 4.2vw, 68px) 20px;
  flex: 1;
}

.hero-copy {
  position: relative;
  z-index: 3;
  max-width: 660px;
}

.hero-logo {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  width: max-content;
  margin: 19px 0 27px;
  font-family: var(--font-display);
  font-size: clamp(76px, 9.2vw, 143px);
  font-weight: 700;
  line-height: 0.69;
  letter-spacing: -0.065em;
  text-transform: uppercase;
  filter: drop-shadow(0 18px 50px rgba(0, 0, 0, 0.36));
}

.logo-heart {
  position: relative;
  color: #fff7f4;
  text-shadow: 0 3px 0 rgba(255, 255, 255, 0.1), 0 8px 24px rgba(0, 0, 0, 0.18);
}

.logo-bite {
  position: relative;
  padding-right: 0.08em;
  color: transparent;
  background: linear-gradient(180deg, #ffd6e5 0%, #ff84b7 36%, var(--accent) 68%, #e32272 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-stroke: 1px rgba(255, 255, 255, 0.14);
  filter: drop-shadow(0 5px 0 #6f113c);
}

.logo-pulse {
  position: absolute;
  top: 0.04em;
  right: -0.18em;
  display: grid;
  place-items: center;
  width: 0.34em;
  height: 0.34em;
  color: var(--accent);
  animation: pulse-heart 3.4s ease-in-out infinite;
}

.logo-pulse svg {
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 0 16px color-mix(in srgb, var(--accent) 60%, transparent));
}

.tagline {
  max-width: 565px;
  color: var(--muted);
  font-size: clamp(17px, 1.45vw, 20px);
  font-weight: 500;
  line-height: 1.5;
}

.tagline strong {
  color: var(--text);
  font-weight: 800;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 11px;
  margin: 30px 0 30px;
}

.hero-metrics {
  display: flex;
  gap: clamp(23px, 3vw, 44px);
  padding: 18px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.hero-metrics div {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.hero-metrics b {
  font-family: var(--font-display);
  font-size: 29px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--text);
}

.hero-metrics span {
  color: var(--muted-2);
  font-family: var(--font-display);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.hero-copy .content-note {
  margin-top: 18px;
}

.hero-art {
  position: relative;
  z-index: 2;
  align-self: stretch;
  min-height: 560px;
  max-height: 720px;
  margin: 0 auto;
  width: 100%;
}

.hero-orbit {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 0;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

.hero-orbit::before {
  content: '';
  position: absolute;
  top: -3px;
  left: 50%;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 12px var(--accent);
}

.orbit-a {
  width: min(51vw, 610px);
  height: min(51vw, 610px);
  animation: spin-slow 40s linear infinite;
}

.orbit-b {
  width: min(43vw, 515px);
  height: min(43vw, 515px);
  border-style: dashed;
  opacity: 0.6;
  animation: spin-slow 60s linear infinite reverse;
}

.orbit-c {
  width: min(61vw, 720px);
  height: min(61vw, 720px);
  opacity: 0.35;
}

.hero-card {
  position: absolute;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.26);
  border-radius: clamp(20px, 2.4vw, 34px);
  background: #1b0b18;
  box-shadow: var(--shadow-deep);
}

.hero-card .portrait-svg {
  transition: transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.hero-card-front {
  top: 50%;
  left: 51%;
  z-index: 3;
  width: auto;
  height: 93%;
  aspect-ratio: 420 / 520;
  transform: translate(-50%, -50%) rotate(2.5deg);
  animation: hero-card-bob 7s ease-in-out infinite;
}

@keyframes hero-card-bob {
  0%, 100% { transform: translate(-50%, -50%) rotate(2.5deg) translateY(0); }
  50% { transform: translate(-50%, -51%) rotate(2.9deg) translateY(-9px); }
}

.hero-card-front::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 2;
  background: linear-gradient(180deg, transparent 52%, rgba(15, 5, 13, 0.1) 62%, rgba(15, 5, 13, 0.9) 100%);
  pointer-events: none;
}

.hero-card-back {
  top: 9%;
  left: 0;
  z-index: 1;
  width: auto;
  height: 72%;
  aspect-ratio: 420 / 520;
  opacity: 0.76;
  transform: rotate(-10deg);
  filter: saturate(0.8) brightness(0.7);
}

.hero-card-top {
  position: absolute;
  top: 16px;
  left: 16px;
  z-index: 4;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 999px;
  background: rgba(10, 4, 12, 0.52);
  backdrop-filter: blur(8px);
  color: #fff;
  font-family: var(--font-display);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.14em;
}

.hero-card-bottom {
  position: absolute;
  bottom: 20px;
  left: 22px;
  z-index: 4;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  color: #fff;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.55);
}

.hero-card-archetype {
  margin-bottom: 3px;
  color: var(--accent-2);
  font-family: var(--font-display);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.hero-card-bottom strong {
  font-family: var(--font-display);
  font-size: clamp(24px, 2.2vw, 34px);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1;
}

.hero-card-handle {
  margin-top: 5px;
  color: rgba(255, 255, 255, 0.68);
  font-size: 10px;
  font-weight: 700;
}

.sticker {
  position: absolute;
  z-index: 5;
  box-shadow: 0 14px 38px rgba(0, 0, 0, 0.28);
}

.sticker-yellow {
  top: 6%;
  right: 1%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 106px;
  height: 106px;
  border-radius: 50%;
  background: #ffd65a;
  color: #2b1705;
  transform: rotate(12deg);
  text-align: center;
  animation: float-y 5.5s ease-in-out infinite;
}

.sticker-yellow::before {
  content: '';
  position: absolute;
  inset: 8px;
  border: 1px dashed rgba(43, 23, 5, 0.34);
  border-radius: 50%;
}

.sticker-yellow span {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: -0.04em;
}

.sticker-yellow strong {
  font-family: var(--font-display);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.07em;
}

.sticker-yellow small {
  margin-top: 2px;
  font-family: var(--font-display);
  font-size: 6.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
}

.sticker-cream {
  top: 12%;
  left: -1%;
  z-index: 6;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px 15px;
  border: 1px solid rgba(53, 23, 38, 0.1);
  border-radius: 9px;
  background: #fff0e8;
  color: #2a0f1e;
  transform: rotate(-7deg);
  animation: float-y 6.5s ease-in-out infinite 0.4s;
}

.sticker-cream .sticker-heart {
  color: var(--accent);
  font-size: 23px;
  line-height: 1;
}

.sticker-cream div {
  display: flex;
  flex-direction: column;
}

.sticker-cream b {
  font-family: var(--font-display);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

.sticker-cream strong {
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.float-chip {
  position: absolute;
  z-index: 6;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 13px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 13px;
  background: rgba(17, 8, 20, 0.74);
  backdrop-filter: blur(13px);
  box-shadow: 0 14px 35px rgba(0, 0, 0, 0.28);
}

.chip-love {
  right: 2%;
  bottom: 12%;
  transform: rotate(-3deg);
}

.chip-voice {
  left: 1%;
  bottom: 5%;
  transform: rotate(3deg);
}

.chip-icon {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  border-radius: 9px;
  background: color-mix(in srgb, var(--accent) 18%, transparent);
  color: var(--accent);
}

.chip-icon svg {
  width: 15px;
  height: 15px;
}

.float-chip div {
  display: flex;
  flex-direction: column;
}

.float-chip small {
  color: var(--muted-2);
  font-family: var(--font-display);
  font-size: 6.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

.float-chip b {
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.float-chip b span {
  color: var(--accent);
}

.voice-bars {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  width: 31px;
  height: 27px;
  color: var(--accent);
}

.voice-bars i {
  display: block;
  width: 2px;
  border-radius: 2px;
  background: currentColor;
  animation: voice-wave 1.1s ease-in-out infinite alternate;
}

.voice-bars i:nth-child(1) { height: 7px; animation-delay: -0.1s; }
.voice-bars i:nth-child(2) { height: 15px; animation-delay: -0.4s; }
.voice-bars i:nth-child(3) { height: 23px; animation-delay: -0.2s; }
.voice-bars i:nth-child(4) { height: 13px; animation-delay: -0.55s; }
.voice-bars i:nth-child(5) { height: 6px; animation-delay: -0.3s; }

@keyframes voice-wave {
  from { transform: scaleY(0.45); opacity: 0.55; }
  to { transform: scaleY(1); opacity: 1; }
}

.hero-spark {
  position: absolute;
  z-index: 5;
  color: var(--accent-2);
  line-height: 1;
  animation: sparkle 3s ease-in-out infinite;
}

.spark-a { top: 24%; right: 4%; font-size: 23px; }
.spark-b { bottom: 17%; left: 5%; font-size: 15px; animation-delay: 0.9s; }
.spark-c { top: 51%; right: 0; font-size: 12px; animation-delay: 1.5s; color: #ffd65a; }

@keyframes sparkle {
  0%, 100% { opacity: 0.4; transform: scale(0.8) rotate(0deg); }
  50% { opacity: 1; transform: scale(1.1) rotate(18deg); }
}

/* --------------------------------------------------------------------------
   Roster
   -------------------------------------------------------------------------- */

.roster-screen {
  background:
    radial-gradient(circle at 12% 5%, rgba(255, 79, 154, 0.12), transparent 28%),
    radial-gradient(circle at 94% 30%, rgba(118, 68, 255, 0.1), transparent 28%),
    linear-gradient(160deg, #0e0713 0%, #08040c 100%);
}

.roster-screen::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background-image: radial-gradient(rgba(255, 255, 255, 0.08) 0.6px, transparent 0.6px);
  background-size: 22px 22px;
  opacity: 0.25;
  mask-image: linear-gradient(to bottom, #000, transparent 80%);
  pointer-events: none;
}

.roster-main {
  width: min(1560px, 100%);
  margin: 0 auto;
  padding: 16px clamp(18px, 3.2vw, 52px) 40px;
}

.roster-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
  margin: 10px 0 27px;
}

.roster-heading h1 {
  margin: 8px 0 9px;
  font-size: clamp(43px, 5.5vw, 76px);
  line-height: 0.92;
  letter-spacing: -0.045em;
}

.roster-heading h1 em {
  color: var(--accent);
  font-style: normal;
}

.roster-lede {
  max-width: 620px;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.55;
}

.roster-note {
  position: relative;
  max-width: 310px;
  flex: 0 0 auto;
  padding: 17px 19px;
  border: 1px solid rgba(255, 79, 154, 0.19);
  border-radius: 16px;
  background: rgba(255, 79, 154, 0.045);
}

.roster-note::before {
  content: '';
  position: absolute;
  top: -5px;
  left: 22px;
  width: 37px;
  height: 9px;
  background: rgba(255, 220, 235, 0.35);
  transform: rotate(-2deg);
}

.note-kicker {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 6px;
  color: var(--accent);
  font-family: var(--font-display);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.15em;
}

.note-kicker svg {
  width: 11px;
  height: 11px;
}

.roster-note p {
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.5;
}

.roster-note p em {
  color: var(--text);
  font-style: normal;
  font-weight: 800;
}

.roster-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: clamp(11px, 1.35vw, 19px);
}

.egirl-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: clamp(15px, 1.5vw, 22px);
  background: #130b1a;
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: transform 0.28s cubic-bezier(0.2, 0.8, 0.2, 1), border-color 0.28s ease, box-shadow 0.28s ease;
}

.egirl-card::before {
  content: '';
  position: absolute;
  inset: auto 0 0;
  z-index: 3;
  height: 2px;
  background: var(--accent);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}

.egirl-card:hover,
.egirl-card:focus-visible {
  z-index: 4;
  border-color: color-mix(in srgb, var(--accent) 52%, rgba(255, 255, 255, 0.2));
  box-shadow: 0 20px 55px rgba(0, 0, 0, 0.42), 0 0 0 1px color-mix(in srgb, var(--accent) 18%, transparent);
  transform: translateY(-7px);
}

.egirl-card:hover::before,
.egirl-card:focus-visible::before {
  transform: scaleX(1);
}

.egirl-card:hover .portrait-svg {
  transform: scale(1.045);
}

.card-art {
  position: relative;
  display: block;
  aspect-ratio: 1 / 0.82;
  overflow: hidden;
  background: var(--char-bg2);
}

.card-art .portrait-svg {
  transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.card-art::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(180deg, transparent 55%, rgba(12, 5, 18, 0.55) 100%);
  pointer-events: none;
}

.card-number,
.card-age {
  position: absolute;
  top: 9px;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 22px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 6px;
  background: rgba(10, 4, 14, 0.45);
  backdrop-filter: blur(7px);
  color: rgba(255, 255, 255, 0.88);
  font-family: var(--font-display);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
}

.card-number { left: 9px; padding: 0 6px; }
.card-age { right: 9px; padding: 0 5px; }

.card-hover {
  position: absolute;
  right: 10px;
  bottom: 10px;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 7px 9px;
  border-radius: 7px;
  background: var(--accent-2);
  color: var(--char-ink);
  font-family: var(--font-display);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  opacity: 0;
  transform: translateY(4px);
  transition: 0.25s ease;
}

.card-hover svg {
  width: 10px;
  height: 10px;
}

.egirl-card:hover .card-hover,
.egirl-card:focus-visible .card-hover {
  opacity: 1;
  transform: translateY(0);
}

.card-sheen {
  position: absolute;
  top: -40%;
  left: -70%;
  z-index: 2;
  width: 45%;
  height: 180%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
  transform: rotate(18deg);
  transition: left 0.55s ease;
  pointer-events: none;
}

.egirl-card:hover .card-sheen {
  left: 125%;
}

.card-info {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 12px 13px 14px;
}

.card-name-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.card-name {
  overflow: hidden;
  font-family: var(--font-display);
  font-size: clamp(14px, 1.15vw, 18px);
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.card-heart {
  color: var(--accent);
  opacity: 0;
  transform: scale(0.6);
  transition: 0.25s ease;
}

.card-heart svg {
  width: 14px;
  height: 14px;
}

.egirl-card:hover .card-heart {
  opacity: 1;
  transform: scale(1);
}

.card-archetype {
  margin-top: 2px;
  color: var(--accent);
  font-family: var(--font-display);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.card-quote {
  display: -webkit-box;
  min-height: 29px;
  margin: 7px 0 10px;
  overflow: hidden;
  color: var(--muted);
  font-size: 10.5px;
  font-style: italic;
  line-height: 1.4;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.card-tags {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-top: auto;
  padding-top: 9px;
  border-top: 1px solid var(--line);
}

.card-tags span {
  overflow: hidden;
  color: var(--muted-2);
  font-family: var(--font-display);
  font-size: 6.5px;
  font-weight: 500;
  letter-spacing: 0.08em;
  line-height: 1.4;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.roster-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: 25px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.roster-footer .content-note {
  max-width: 720px;
}

.roster-counter {
  flex: 0 0 auto;
  color: var(--muted-2);
  font-family: var(--font-display);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.14em;
}

/* ==========================================================================
   HEARTBITE — date scene + swallow transition
   ========================================================================== */

.date-screen {
  overflow: hidden;
  background:
    radial-gradient(circle at 18% 22%, color-mix(in srgb, var(--accent) 18%, transparent), transparent 36%),
    radial-gradient(circle at 87% 75%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 32%),
    linear-gradient(135deg, #0b0610 0%, var(--char-bg2) 190%);
}

.date-screen::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background-image:
    radial-gradient(rgba(255, 255, 255, 0.11) 0.6px, transparent 0.6px),
    linear-gradient(115deg, transparent 0 68%, rgba(255, 255, 255, 0.025) 68% 68.2%, transparent 68.2%);
  background-size: 20px 20px, 100% 100%;
  opacity: 0.23;
  mask-image: linear-gradient(90deg, #000, transparent 40%, transparent 60%, #000);
  pointer-events: none;
}

.date-screen::after {
  content: '♥';
  position: absolute;
  right: -2vw;
  bottom: -12vw;
  z-index: 0;
  color: color-mix(in srgb, var(--accent) 6%, transparent);
  font-family: var(--font-display);
  font-size: 41vw;
  line-height: 0.7;
  transform: rotate(-10deg);
  pointer-events: none;
}

.date-bg-orb {
  position: absolute;
  z-index: 0;
  border-radius: 50%;
  filter: blur(80px);
  pointer-events: none;
}

.orb-one {
  top: 16%;
  left: 14%;
  width: 260px;
  height: 260px;
  background: var(--accent);
  opacity: 0.14;
}

.orb-two {
  right: 7%;
  bottom: 7%;
  width: 330px;
  height: 330px;
  background: var(--accent);
  opacity: 0.08;
}

.date-screen.is-shaking {
  animation: screen-shake 0.46s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
}

@keyframes screen-shake {
  10%, 90% { transform: translateX(-2px); }
  20%, 80% { transform: translateX(4px) rotate(-0.15deg); }
  30%, 50%, 70% { transform: translateX(-7px) rotate(0.15deg); }
  40%, 60% { transform: translateX(7px) rotate(-0.1deg); }
}

.date-layout {
  display: grid;
  grid-template-columns: minmax(370px, 0.92fr) minmax(470px, 1.08fr);
  align-items: stretch;
  gap: clamp(15px, 2vw, 28px);
  width: min(1480px, 100%);
  margin: 0 auto;
  padding: 6px clamp(16px, 3.2vw, 50px) 20px;
  flex: 1;
}

/* --------------------------------------------------------------------------
   Portrait stage
   -------------------------------------------------------------------------- */

.date-stage {
  position: relative;
  min-height: 600px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 34%, rgba(255, 255, 255, 0.1));
  border-radius: var(--radius-xl);
  background: var(--char-bg2);
  box-shadow: var(--shadow-deep);
  isolation: isolate;
}

.date-stage::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 2;
  background:
    linear-gradient(180deg, rgba(8, 3, 11, 0.03) 0%, transparent 50%, rgba(8, 3, 11, 0.88) 100%),
    radial-gradient(circle at 50% 38%, transparent 40%, rgba(8, 3, 11, 0.12) 100%);
  pointer-events: none;
}

.stage-noise {
  position: absolute;
  inset: 0;
  z-index: 3;
  opacity: 0.13;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.38'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
  pointer-events: none;
}

.stage-halo {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 0;
  width: 87%;
  aspect-ratio: 1;
  border: 1px solid rgba(255, 255, 255, 0.17);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 0 35px rgba(255, 255, 255, 0.025), 0 0 0 70px rgba(255, 255, 255, 0.015);
}

.stage-halo::before,
.stage-halo::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  border: 1px dashed rgba(255, 255, 255, 0.14);
}

.stage-halo::before { inset: 12%; animation: spin-slow 55s linear infinite; }
.stage-halo::after { inset: -13%; border-color: rgba(255, 255, 255, 0.07); }

.stage-portrait {
  position: absolute;
  inset: 0;
  z-index: 1;
  transform-origin: 50% 65%;
  animation: portrait-breathe 7s ease-in-out infinite;
}

@keyframes portrait-breathe {
  0%, 100% { transform: scale(1) translateY(0); }
  50% { transform: scale(1.006) translateY(-5px); }
}

.stage-portrait .portrait-svg {
  height: 100%;
}

.stage-portrait.is-reacting.tone-good {
  animation: portrait-happy 0.65s ease both;
}

.stage-portrait.is-reacting.tone-bad {
  animation: portrait-stung 0.6s ease both;
}

@keyframes portrait-happy {
  0% { transform: scale(1); }
  38% { transform: scale(1.025) rotate(-0.7deg); }
  70% { transform: scale(1.012) rotate(0.4deg); }
  100% { transform: scale(1); }
}

@keyframes portrait-stung {
  0% { transform: scale(1); filter: saturate(1); }
  30% { transform: scale(1.018) rotate(0.8deg); filter: saturate(0.7); }
  60% { transform: scale(0.994) rotate(-0.5deg); }
  100% { transform: scale(1); filter: saturate(1); }
}

.stage-topline {
  position: absolute;
  top: 18px;
  right: 18px;
  left: 18px;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  pointer-events: none;
}

.route-pill,
.stage-age {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 11px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  background: rgba(11, 4, 13, 0.45);
  backdrop-filter: blur(10px);
  color: #fff;
  font-family: var(--font-display);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

.route-pill .live-dot {
  width: 5px;
  height: 5px;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.08);
}

.stage-age {
  padding: 7px 9px;
  color: rgba(255, 255, 255, 0.68);
}

.stage-nameplate {
  position: absolute;
  bottom: 31px;
  left: 28px;
  z-index: 5;
  max-width: 76%;
  color: #fff;
  text-shadow: 0 2px 20px rgba(0, 0, 0, 0.42);
}

.nameplate-archetype {
  display: inline-flex;
  margin-bottom: 5px;
  padding: 4px 8px;
  border-radius: 4px;
  background: var(--accent);
  color: var(--char-ink);
  font-family: var(--font-display);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.stage-nameplate h2 {
  font-size: clamp(34px, 3.6vw, 53px);
  line-height: 0.96;
  letter-spacing: -0.045em;
}

.nameplate-handle {
  display: block;
  margin-top: 7px;
  color: rgba(255, 255, 255, 0.56);
  font-size: 10px;
  font-weight: 700;
}

.stage-voice {
  position: absolute;
  right: 24px;
  bottom: 30px;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 11px 7px 8px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 10px;
  background: rgba(12, 4, 15, 0.54);
  backdrop-filter: blur(9px);
  color: rgba(255, 255, 255, 0.72);
  font-size: 8px;
  font-weight: 700;
  line-height: 1.2;
}

.stage-voice .voice-bars {
  width: 22px;
  height: 20px;
}

.stage-voice .voice-bars i {
  width: 1.5px;
}

.stage-voice span:last-child {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.stage-voice small {
  color: var(--accent-2);
  font-family: var(--font-display);
  font-size: 5.5px;
  letter-spacing: 0.14em;
}

.stage-heart-note {
  position: absolute;
  top: 22%;
  right: 16px;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding: 9px 10px;
  border-right: 2px solid var(--accent);
  background: linear-gradient(90deg, transparent, rgba(12, 4, 15, 0.32));
  text-shadow: 0 1px 10px rgba(0, 0, 0, 0.5);
}

.stage-heart-note > span {
  color: var(--accent);
  font-size: 13px;
  line-height: 1;
}

.stage-heart-note small {
  margin-top: 3px;
  color: rgba(255, 255, 255, 0.52);
  font-family: var(--font-display);
  font-size: 5.5px;
  letter-spacing: 0.12em;
}

.stage-heart-note strong {
  margin-top: 1px;
  color: #fff;
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

/* --------------------------------------------------------------------------
   Chat
   -------------------------------------------------------------------------- */

.chat-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
  padding: clamp(14px, 1.7vw, 22px);
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: var(--radius-xl);
  background:
    linear-gradient(155deg, rgba(255, 255, 255, 0.035), transparent 42%),
    rgba(14, 8, 18, 0.82);
  box-shadow: var(--shadow-deep);
  backdrop-filter: blur(16px);
}

.love-panel {
  padding: 13px 15px 12px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.025);
}

.love-heading {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 8px;
}

.love-title {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  font-family: var(--font-display);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

.love-title svg {
  width: 10px;
  height: 10px;
  color: var(--accent);
}

.love-status {
  padding: 3px 7px;
  border: 1px solid color-mix(in srgb, var(--accent) 25%, transparent);
  border-radius: 99px;
  background: color-mix(in srgb, var(--accent) 9%, transparent);
  color: var(--accent-2);
  font-family: var(--font-display);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.love-value {
  margin-left: auto;
  color: var(--text);
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.03em;
}

.love-value small {
  color: var(--muted-2);
  font-size: 9px;
  letter-spacing: 0;
}

.love-track {
  position: relative;
  height: 19px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 99px;
  background: rgba(0, 0, 0, 0.27);
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.3);
}

.love-fill {
  position: absolute;
  inset: 2px auto 2px 2px;
  min-width: 3px;
  width: 50%;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  box-shadow: 0 0 18px color-mix(in srgb, var(--accent) 55%, transparent);
  transition: width 0.82s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.3s ease;
}

.love-panel.is-low .love-fill {
  background: linear-gradient(90deg, #ff395f, #ff8b9d);
}

.love-panel.is-full .love-fill {
  background: linear-gradient(90deg, #ff2f6d, #ff8abb, #ffe4f0, #ff8abb, #ff2f6d);
  background-size: 180% 100%;
  animation: full-love 1.8s linear infinite;
}

@keyframes full-love {
  to { background-position: 180% 0; }
}

.love-shine {
  position: absolute;
  inset: 2px;
  z-index: 2;
  border-radius: 99px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.32), transparent 48%);
  pointer-events: none;
}

.love-tick {
  position: absolute;
  top: 4px;
  bottom: 4px;
  z-index: 3;
  width: 1px;
  background: rgba(8, 3, 11, 0.43);
}

.love-tick.t1 { left: 20%; }
.love-tick.t2 { left: 40%; }
.love-tick.t3 { left: 60%; }
.love-tick.t4 { left: 80%; }

.love-hint {
  margin-top: 6px;
  color: var(--muted-2);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.love-panel.is-low .love-hint {
  color: #ff9aab;
}

.love-panel.is-full .love-hint {
  color: var(--accent-2);
}

.dialogue-card {
  position: relative;
  flex: 0 1 auto;
  padding: clamp(15px, 1.7vw, 22px) clamp(17px, 1.9vw, 25px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 19px;
  background:
    radial-gradient(circle at 100% 0, color-mix(in srgb, var(--accent) 8%, transparent), transparent 45%),
    rgba(255, 255, 255, 0.035);
}

.dialogue-meta {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 9px;
}

.speaker-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  box-shadow: 0 0 8px currentColor;
}

.speaker-name {
  color: var(--accent-2);
  font-family: var(--font-display);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

.beat-count {
  margin-left: auto;
  color: var(--muted-2);
  font-family: var(--font-display);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.1em;
}

.dialogue-text {
  color: var(--text);
  font-family: var(--font-display);
  font-size: clamp(18px, 1.62vw, 24px);
  font-weight: 500;
  line-height: 1.3;
  letter-spacing: -0.015em;
}

.speech-tail {
  position: absolute;
  bottom: -7px;
  left: 35px;
  width: 13px;
  height: 13px;
  border-right: 1px solid rgba(255, 255, 255, 0.1);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  background: #1b111f;
  transform: rotate(45deg);
}

/* --------------------------------------------------------------------------
   Options
   -------------------------------------------------------------------------- */

.options-wrap {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.options-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 7px;
  color: var(--muted);
  font-family: var(--font-display);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
}

.options-hint {
  color: var(--muted-2);
  font-family: var(--font-body);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0;
}

.options-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  flex: 1;
}

.option-btn {
  position: relative;
  display: grid;
  grid-template-columns: 29px minmax(0, 1fr) 15px;
  align-items: center;
  gap: 9px;
  min-height: 78px;
  padding: 11px 12px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 13px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.018));
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease;
}

.option-btn::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  background: linear-gradient(110deg, color-mix(in srgb, var(--accent) 13%, transparent), transparent 65%);
  opacity: 0;
  transition: opacity 0.2s ease;
}

.option-btn:hover {
  border-color: color-mix(in srgb, var(--accent) 56%, transparent);
  background: rgba(255, 255, 255, 0.065);
  transform: translateY(-2px);
}

.option-btn:hover::before {
  opacity: 1;
}

.option-key {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, rgba(255, 255, 255, 0.12));
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  color: var(--accent-2);
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 600;
}

.option-text {
  position: relative;
  z-index: 1;
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.35;
}

.option-arrow {
  position: relative;
  z-index: 1;
  color: var(--accent);
  opacity: 0;
  transform: translateX(-3px);
  transition: 0.2s ease;
}

.option-arrow svg {
  width: 14px;
  height: 14px;
}

.option-btn:hover .option-arrow {
  opacity: 1;
  transform: translateX(0);
}

/* --------------------------------------------------------------------------
   Reaction
   -------------------------------------------------------------------------- */

.answer-reaction {
  display: flex;
  flex-direction: column;
  flex: 1;
  gap: 9px;
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.025);
  animation: reaction-in 0.34s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes reaction-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.you-said {
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.035);
}

.mini-label {
  display: block;
  margin-bottom: 4px;
  color: var(--muted-2);
  font-family: var(--font-display);
  font-size: 6.5px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

.you-said p {
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 700;
  line-height: 1.35;
}

.her-reply {
  flex: 1;
  padding: 13px 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 24%, transparent);
  border-radius: 13px;
  background:
    radial-gradient(circle at 100% 0, color-mix(in srgb, var(--accent) 12%, transparent), transparent 52%),
    rgba(255, 255, 255, 0.025);
}

.her-reply .mini-label {
  color: var(--accent-2);
}

.her-reply p {
  color: var(--text);
  font-family: var(--font-display);
  font-size: clamp(16px, 1.4vw, 20px);
  font-weight: 500;
  line-height: 1.32;
}

.answer-reaction[data-tone="good"] .her-reply {
  border-color: rgba(98, 234, 176, 0.28);
  background: radial-gradient(circle at 100% 0, rgba(98, 234, 176, 0.11), transparent 52%), rgba(255, 255, 255, 0.025);
}

.answer-reaction[data-tone="bad"] .her-reply {
  border-color: rgba(255, 85, 120, 0.27);
  background: radial-gradient(circle at 100% 0, rgba(255, 85, 120, 0.1), transparent 52%), rgba(255, 255, 255, 0.025);
}

.reaction-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.reaction-readout {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.delta-chip,
.tone-chip {
  display: inline-flex;
  align-items: center;
  height: 24px;
  padding: 0 9px;
  border-radius: 99px;
  font-family: var(--font-display);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.delta-chip.good {
  background: rgba(98, 234, 176, 0.13);
  color: var(--good);
  border: 1px solid rgba(98, 234, 176, 0.25);
}

.delta-chip.bad {
  background: rgba(255, 85, 120, 0.13);
  color: var(--bad);
  border: 1px solid rgba(255, 85, 120, 0.25);
}

.delta-chip.neutral {
  background: rgba(201, 178, 220, 0.09);
  color: var(--neutral);
  border: 1px solid rgba(201, 178, 220, 0.18);
}

.tone-chip {
  color: var(--muted-2);
  border: 1px solid var(--line);
}

.next-btn {
  min-height: 39px;
  padding: 0 15px;
  font-size: 9px;
}

.date-footnote {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: auto;
  padding-top: 2px;
  color: var(--muted-2);
  font-family: var(--font-display);
  font-size: 6.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
}

.date-footnote span:first-child {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.date-footnote svg {
  width: 9px;
  height: 9px;
  color: var(--accent);
}

.date-footnote-right {
  color: color-mix(in srgb, var(--accent) 75%, white);
  text-align: right;
}

/* --------------------------------------------------------------------------
   Heart burst
   -------------------------------------------------------------------------- */

.heart-burst-layer {
  position: absolute;
  inset: 0;
  z-index: 8;
  overflow: hidden;
  pointer-events: none;
}

.burst-heart {
  position: absolute;
  font-family: var(--font-display);
  font-size: 18px;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
  animation: burst-heart 1.35s cubic-bezier(0.16, 0.8, 0.3, 1) both;
}

@keyframes burst-heart {
  0% { opacity: 0; transform: translate(0, 0) scale(0.4) rotate(0); }
  15% { opacity: 1; }
  100% { opacity: 0; transform: translate(var(--dx), var(--dy)) scale(0.9) rotate(var(--rot)); }
}

/* --------------------------------------------------------------------------
   Swallow transition
   -------------------------------------------------------------------------- */

.swallow-screen {
  position: relative;
  display: grid;
  place-items: center;
  overflow: hidden;
  min-height: 100svh;
  background:
    radial-gradient(circle at 50% 48%, color-mix(in srgb, var(--accent) 33%, transparent), transparent 45%),
    radial-gradient(circle at 50% 50%, #180817 0%, #070309 66%);
}

.swallow-bad {
  background:
    radial-gradient(circle at 50% 48%, rgba(255, 35, 86, 0.25), transparent 45%),
    radial-gradient(circle at 50% 50%, #18070c 0%, #050204 66%);
}

.swallow-vignette {
  position: absolute;
  inset: 0;
  z-index: 3;
  background: radial-gradient(circle, transparent 20%, rgba(4, 1, 6, 0.88) 90%);
  pointer-events: none;
}

.swallow-rings {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 1;
  width: min(80vw, 900px);
  aspect-ratio: 1;
  transform: translate(-50%, -50%);
}

.swallow-rings i {
  position: absolute;
  inset: 0;
  border: 1px solid color-mix(in srgb, var(--accent) 46%, transparent);
  border-radius: 50%;
  animation: swallow-ring 2.4s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.swallow-rings i:nth-child(2) { animation-delay: 0.18s; }
.swallow-rings i:nth-child(3) { animation-delay: 0.36s; }
.swallow-rings i:nth-child(4) { animation-delay: 0.54s; }

@keyframes swallow-ring {
  0% { opacity: 0; transform: scale(0.45); }
  28% { opacity: 0.8; }
  100% { opacity: 0; transform: scale(1.12); }
}

.swallow-portrait {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 0;
  width: min(540px, 60vw);
  aspect-ratio: 420 / 520;
  transform: translate(-50%, -50%) scale(1.12);
  opacity: 0.42;
  filter: blur(1px) saturate(0.72);
  mask-image: radial-gradient(circle at 50% 45%, #000 20%, transparent 74%);
  animation: swallow-portrait 2.4s cubic-bezier(0.3, 0, 0.3, 1) both;
}

@keyframes swallow-portrait {
  0% { transform: translate(-50%, -50%) scale(1.35); opacity: 0; }
  30% { opacity: 0.46; }
  100% { transform: translate(-50%, -50%) scale(0.92); opacity: 0; }
}

.swallow-copy {
  position: relative;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(760px, 88vw);
  text-align: center;
  animation: swallow-copy 2.4s ease both;
}

@keyframes swallow-copy {
  0% { opacity: 0; transform: translateY(18px) scale(0.96); filter: blur(4px); }
  25%, 78% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
  100% { opacity: 0; transform: scale(1.05); filter: blur(4px); }
}

.swallow-copy h1 {
  margin: 9px 0 15px;
  font-size: clamp(54px, 8vw, 112px);
  font-weight: 700;
  line-height: 0.82;
  letter-spacing: -0.055em;
  text-transform: uppercase;
}

.swallow-good .swallow-copy h1 {
  color: transparent;
  background: linear-gradient(180deg, #fff, var(--accent-2) 45%, var(--accent));
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 40px color-mix(in srgb, var(--accent) 50%, transparent));
}

.swallow-bad .swallow-copy h1 {
  color: #ffd9df;
  text-shadow: 0 0 30px rgba(255, 38, 89, 0.5), 3px 0 0 rgba(255, 38, 89, 0.35), -3px 0 0 rgba(88, 221, 255, 0.18);
}

.swallow-line {
  max-width: 620px;
  color: rgba(255, 255, 255, 0.78);
  font-family: var(--font-display);
  font-size: clamp(14px, 1.5vw, 19px);
  font-weight: 500;
  line-height: 1.45;
}

.swallow-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 24px;
  padding: 8px 13px;
  border: 1px solid rgba(255, 255, 255, 0.17);
  border-radius: 99px;
  background: rgba(10, 4, 12, 0.38);
  color: rgba(255, 255, 255, 0.58);
  font-family: var(--font-display);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.13em;
}

.swallow-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 10px var(--accent);
  animation: dot-pulse 1.1s ease-in-out infinite;
}

.swallow-bad .swallow-dot {
  background: #ff315c;
  box-shadow: 0 0 10px #ff315c;
}

.swallow-heart {
  position: absolute;
  bottom: 9%;
  left: 50%;
  z-index: 4;
  color: var(--accent);
  transform: translateX(-50%);
  opacity: 0;
  animation: swallow-heart 1.5s ease-out 0.4s both;
}

.swallow-heart svg {
  width: 33px;
  height: 33px;
}

@keyframes swallow-heart {
  0% { opacity: 0; transform: translate(-50%, 20px) scale(0.3) rotate(-15deg); }
  25% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -160px) scale(1.2) rotate(16deg); }
}

.swallow-flash {
  position: absolute;
  inset: 0;
  z-index: 6;
  background: #fff;
  opacity: 0;
  pointer-events: none;
  animation: swallow-flash 2.4s ease both;
}

@keyframes swallow-flash {
  0%, 82% { opacity: 0; }
  88% { opacity: 0.55; }
  100% { opacity: 0; }
}
